   133	func listDeleteUserMemoTreeRecursive(ctx context.Context, tx *sql.Tx, userID int32) ([]deleteUserMemoRef, error) {
   134		rows, err := tx.QueryContext(ctx, `
   135			WITH RECURSIVE memo_tree(id, uid) AS (
   136				SELECT id, uid
   137				FROM memo
   138				WHERE creator_id = `+deleteUserPlaceholder(1)+`
   139				UNION
   140				SELECT child.id, child.uid
   141				FROM memo child
   142				JOIN memo_relation rel ON rel.memo_id = child.id AND rel.type = 'COMMENT'
   143				JOIN memo_tree parent ON rel.related_memo_id = parent.id
   144			)
   145			SELECT id, uid
   146			FROM memo_tree
   147		`, userID)
   148		if err != nil {
   149			return nil, err
   150		}
   151		defer rows.Close()
   152	
   153		memos := make([]deleteUserMemoRef, 0)
   154		for rows.Next() {
   155			var memo deleteUserMemoRef
